//! CDK parity test.
//!
//! Compares FerrumChem's CDK-derived descriptors against CDK 2.13
//! (`tests/data/cdk_parity_reference.csv`, generated by
//! `scripts/cdk_reference/run.sh`). Mechanics and baseline handling are the same
//! as in `rdkit_parity.rs`; known deviations are tracked in
//! `tests/data/cdk_parity_baseline.tsv`.
//!
//! CDK perceives aromaticity with its own model; FerrumChem has exactly one
//! chemistry model (RDKit's). Descriptors that depend on aromaticity can
//! therefore differ for molecules where the two models disagree.
//!
//! ```text
//! FERRUM_UPDATE_PARITY_BASELINE=1 cargo test -p ferrum_core --release --test cdk_parity
//! FERRUM_PARITY_VERBOSE=1 cargo test -p ferrum_core --release --test cdk_parity -- --nocapture
//! ```

mod common;

#[test]
fn cdk_parity() {
    common::parity::run_parity("CDK", "cdk_parity_reference.csv", "cdk_parity_baseline.tsv");
}
